-- Bu migration rn_ təhlükəsizlik metadata-sına toxunur; ayrıca razılıq olmadan canlı DB-yə tətbiq edilməməlidir.
WITH parent AS (SELECT id,sistem_id FROM public.rn_modullar WHERE kod='MIS_PARAM') INSERT INTO public.rn_modullar(sistem_id,parent_id,kod,ad,aciqlama,route,ikon,menyuda_gorunsun,aktiv,sira_no) SELECT sistem_id,id,'APP_REASONS','Səbəblər','Sistem əməliyyatlarında istifadə olunan səbəb kataloqu','/parametrler/sebebler','ti ti-message-question',true,true,78 FROM parent ON CONFLICT(kod) DO UPDATE SET parent_id=EXCLUDED.parent_id,ad=EXCLUDED.ad,aciqlama=EXCLUDED.aciqlama,route=EXCLUDED.route,ikon=EXCLUDED.ikon,menyuda_gorunsun=true,aktiv=true,sira_no=EXCLUDED.sira_no;
