INSERT INTO public.rn_selahiyyetler(modul_id,kod,ad,aciqlama,aktiv) SELECT m.id,v.kod,v.ad,v.aciqlama,true FROM public.rn_modullar m CROSS JOIN (VALUES ('SEBEB_BAX','Səbəblərə bax','Səbəb növlərini və səbəbləri görmək'),('SEBEB_IDARE_ET','Səbəbləri idarə et','Səbəb yaratmaq və yeniləmək'))v(kod,ad,aciqlama) WHERE m.kod='APP_REASONS' ON CONFLICT(kod) DO UPDATE SET modul_id=EXCLUDED.modul_id,ad=EXCLUDED.ad,aciqlama=EXCLUDED.aciqlama,aktiv=true;
INSERT INTO public.rn_route_selahiyyetleri(route,http_metod,selahiyyet_kodu,aktiv) VALUES('/parametrler/sebebler/yeni','POST','SEBEB_IDARE_ET',true),('/parametrler/sebebler/yenile','POST','SEBEB_IDARE_ET',true) ON CONFLICT(route,http_metod) DO UPDATE SET selahiyyet_kodu=EXCLUDED.selahiyyet_kodu,aktiv=true;
INSERT INTO public.rn_rol_modullari(rol_id,modul_id,aktiv) SELECT r.id,m.id,true FROM public.rn_rollar r CROSS JOIN public.rn_modullar m WHERE r.sistem_roludur AND r.aktiv AND m.kod='APP_REASONS' ON CONFLICT(rol_id,modul_id) DO UPDATE SET aktiv=true;
INSERT INTO public.rn_rol_selahiyyetleri(rol_id,selahiyyet_id,aktiv) SELECT r.id,s.id,true FROM public.rn_rollar r CROSS JOIN public.rn_selahiyyetler s WHERE r.sistem_roludur AND r.aktiv AND s.kod IN('SEBEB_BAX','SEBEB_IDARE_ET') ON CONFLICT(rol_id,selahiyyet_id) DO UPDATE SET aktiv=true;
